/// <summary>
/// When <c>METInventOnhandItemFormSyncUpSystemDefinedFilterPaneFlight</c> is enabled, the the ranges on filtering pane will be synced up with the filters on the grid.
/// </summary>
internal final class METInventOnhandItemFormSyncUpSystemDefinedFilterPaneFlight extends Flight
{
    static private METInventOnhandItemFormSyncUpSystemDefinedFilterPaneFlight singleton = new METInventOnhandItemFormSyncUpSystemDefinedFilterPaneFlight();

}

Method.Source:
/// <summary>
/// /// This flight is enabled by default, so that the system defined filter pane will be synced up with the filters on the grid.
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
protected boolean isEnabledByDefault()
{
    return true;
}

/// <summary>
/// /// Returns the singleton instance of the flight.
/// </summary>
/// <returns>METInventOnhandItemFormSyncUpSystemDefinedFilterPaneFlight</returns>
[Hookable(false)]
public static METInventOnhandItemFormSyncUpSystemDefinedFilterPaneFlight instance()
{
    return singleton;
}
